    private static final int GRAPH_VERTICES = 6;
    private static final int[][] EDGES = {
        {0, 1}, {1, 2}, {2, 3}, {4, 5}, {5, 1}, {5, 2}
    };

    public static void main(String[] args) {
        DirectedAcyclicGraph graph = DirectedAcyclicGraph.builder(GRAPH_VERTICES)
            .edge(0, 1)
