public class TestRefactoring {
    public static void main(String[] args) {
        System.out.println("Test 1: Builder Pattern");
        DirectedAcyclicGraph graph = DirectedAcyclicGraph.builder(4)
            .edge(0, 1)
            .edge(1, 2)
            .edge(2, 3)
            .build();
        System.out.println("Built successfully: " + graph.topologicalSort());

        System.out.println("\nTest 2: Immutability after sort");
        try {
            graph.addEdge(0, 2);
        } catch (IllegalStateException e) {
            System.out.println("Caught: " + e.getMessage());
        }

        System.out.println("\nTest 3: Result immutability");
        DirectedAcyclicGraph g = DirectedAcyclicGraph.builder(2)
            .edge(0, 1)
            .build();
        TopologicalSortResult result = g.topologicalSort();
        try {
            result.getOrder().add(99);
        } catch (UnsupportedOperationException e) {
            System.out.println("Caught: Cannot modify result list");
        }

        System.out.println("\nTest 4: Result metadata");
        System.out.println("Order size: " + result.getProcessedVertices());
        System.out.println("Is complete: " + result.isComplete());
        System.out.println("Is cyclic: " + result.isCyclic());
    }
}
EOF
